export const DEFAULT_LOGO_DATA_URL = 'data:image/png;base64,';

const DATA_IMAGE_RE = /^data:image\/(png|jpe?g|webp|svg\+xml);/i;
const SAFE_SOURCE_RE = /^(data:image\/|blob:|https?:\/\/|\/|\.\/|\.\.\/)/i;

function cleanLogoValue(value) {
  if (typeof value !== 'string') return '';
  const trimmed = value.trim();
  if (!trimmed) return '';
  if (DATA_IMAGE_RE.test(trimmed) || /^(blob:|https?:\/\/|\/|\.\/|\.\.\/)/i.test(trimmed)) return trimmed;
  if (/^www\./i.test(trimmed)) return `https://${trimmed}`;
  return trimmed;
}

function dataUrlToBlob(dataUrl) {
  const [head, data = ''] = String(dataUrl || '').split(',');
  const mime = (head.match(/data:([^;]+)/i) || [])[1] || 'image/png';
  const binary = atob(data);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return new Blob([bytes], { type: mime });
}

function blobToDataUrl(blob) {
  return new Promise((resolve, reject) => {
    if (!(blob instanceof Blob)) return reject(new Error('blob-required'));
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ''));
    reader.onerror = () => reject(reader.error || new Error('read-failed'));
    reader.readAsDataURL(blob);
  });
}

async function fetchImageAsDataUrl(src) {
  const url = cleanLogoValue(src);
  if (!url || DATA_IMAGE_RE.test(url)) return url || '';
  try {
    const response = await fetch(url, { mode: 'cors', credentials: 'omit', cache: 'no-store' });
    if (!response.ok) throw new Error(`http-${response.status}`);
    const contentType = String(response.headers.get('content-type') || '').toLowerCase();
    if (contentType && !contentType.startsWith('image/')) throw new Error('not-image');
    const blob = await response.blob();
    if (!(blob instanceof Blob) || !blob.size) throw new Error('empty-image');
    return await blobToDataUrl(blob);
  } catch (_) {
    return '';
  }
}

export async function materializeLogoSource(input) {
  const normalized = cleanLogoValue(input);
  if (!normalized) return { logoUrl: '', logoSourceUrl: '' };
  if (DATA_IMAGE_RE.test(normalized)) return { logoUrl: normalized, logoSourceUrl: '' };
  const cached = await fetchImageAsDataUrl(normalized);
  return { logoUrl: cached || '', logoSourceUrl: normalized };
}

export function getBrandLogoDisplayUrl(settings) {
  const display = cleanLogoValue(settings?.logoSourceUrl) || cleanLogoValue(settings?.logoUrl);
  return SAFE_SOURCE_RE.test(display) ? display : DEFAULT_LOGO_DATA_URL;
}

export function getBrandLogoDataUrl(settings) {
  const value = cleanLogoValue(settings?.logoUrl);
  if (DATA_IMAGE_RE.test(value)) return value;
  const fallback = cleanLogoValue(settings?.logoSourceUrl);
  if (DATA_IMAGE_RE.test(fallback)) return fallback;
  return DEFAULT_LOGO_DATA_URL;
}
